{
  "summary": "Participants can request an audit of the Joint Venture books, performed by an acceptable accounting firm and paid for by the Joint Venture, with a limit of one audit per fiscal year.",
  "evidence": [
    {
      "passage_id": 1,
      "quote": "Any of the Participants will have the right to request an audit of the Joint Venture books."
    },
    {
      "passage_id": 1,
      "quote": "The cost of the audit will be borne by the Joint Venture."
    },
    {
      "passage_id": 1,
      "quote": "The audit will be performed by an accounting firm acceptable to all the Participants."
    },
    {
      "passage_id": 1,
      "quote": "Not more than one (1) audit will be required by any or all of the Participants for any fiscal year."
    }
  ]
}
